    async def versiones(self, *, status: Optional[Literal["awaiting_approval", "approved", "active", "superseded", "rolled_back", "rejected", "expired", "failed"]] = None, slug: Optional[Union[str, int]] = None, limit: Optional[int] = None, offset: Optional[int] = None, agent_id: Optional[Union[str, int]] = None, request_options: Optional[RequestOptions] = None) -> Outcome[VersionesResult]:
        """Code versions (pipeline)

        Every agent's drafts and versions, newest first, with test, scan and decision summaries.

        REST: `GET /api/approvals/promotion/versions` · scope `kon:promotion-admin:versiones`
        idempotent (safe to retry)
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
        """
        return await self._call(OPERATIONS["versiones"], {"status": status, "slug": slug, "limit": limit, "offset": offset, "agentId": agent_id}, None, request_options)

    def iter_versiones(self, *, status: Optional[Literal["awaiting_approval", "approved", "active", "superseded", "rolled_back", "rejected", "expired", "failed"]] = None, slug: Optional[Union[str, int]] = None, limit: Optional[int] = None, agent_id: Optional[Union[str, int]] = None, request_options: Optional[RequestOptions] = None) -> AsyncIterator[Dict[str, Any]]:
        """Every item of `versiones`, page after page (moves `offset`).

        Stops on an empty or short page, or when the response says there is no more. Raises `ProposalPendingError` if a page needs human approval.
        """
        return self._iterate(OPERATIONS["versiones"], {"status": status, "slug": slug, "limit": limit, "agentId": agent_id}, request_options)

    async def volver_atras(self, *, id: Union[str, int], body: VolverAtrasBody, request_options: Optional[RequestOptions] = None) -> Outcome[VolverAtrasResult]:
        """Roll back an active version

        Restores the version that was active before this one (or pauses the action if this was its first version). Only from the active version. Audited and notified.

        REST: `POST /api/approvals/promotion/versions/{id}/rollback` · scope `kon:promotion-admin:volver-atras`
        not idempotent (an Idempotency-Key is sent automatically)
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
        """
        return await self._call(OPERATIONS["volver-atras"], {"id": id}, body, request_options)
